-- =============================================================================
-- 0022_articulos.sql   (requiere 0021 ya aplicado)
-- Que hace:
--   * CATALOGO DE ARTICULOS: los 987 articulos del sistema de ESC (clave, nombre, clave SAT, ultima compra
--     y estatus). Solo se pueden elegir en la bitacora los que estan Activos o en "Suspension de compras"
--     (aun hay existencia para vender). "Suspension de compras/ventas" y "Baja" se guardan para consulta.
--   * La familia (Guante, Bata, Wipe, Zapato...) sale de la primera palabra del nombre, para filtrar.
--   * BITACORA: cada registro de ventas o prospeccion puede llevar los articulos que se vendieron u ofrecieron.
--   * Volver a correr este archivo actualiza el catalogo por clave (no duplica).
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run (una sola ejecucion).
-- =============================================================================

begin;

create table if not exists public.articulos (
  id uuid primary key default gen_random_uuid(),
  clave text not null unique check (length(clave) between 1 and 60),
  nombre text not null check (length(nombre) between 2 and 300),
  familia text not null default 'Otro',
  clave_sat text,
  ultima_compra date,
  estatus text not null check (estatus in ('activo', 'suspension_compras', 'suspension_compras_ventas', 'baja')),
  vendible boolean generated always as (estatus in ('activo', 'suspension_compras')) stored,
  busqueda text generated always as (translate(lower(clave || ' ' || nombre), 'áéíóúüñ', 'aeiouun')) stored,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists articulos_familia_idx on public.articulos (familia) where vendible;
drop trigger if exists articulos_updated on public.articulos;
create trigger articulos_updated before update on public.articulos for each row execute function public.set_updated_at();
drop trigger if exists articulos_audit on public.articulos;
create trigger articulos_audit after update on public.articulos for each row execute function public.audit_row();

alter table public.articulos enable row level security;
revoke all on public.articulos from anon, authenticated;
grant select on public.articulos to authenticated;
grant update (nombre, familia, clave_sat, estatus) on public.articulos to authenticated;
drop policy if exists articulos_select on public.articulos;
create policy articulos_select on public.articulos for select to authenticated using (public.is_active_user());
drop policy if exists articulos_update on public.articulos;
create policy articulos_update on public.articulos for update to authenticated using (public.is_buyer()) with check (public.is_buyer());

on conflict (clave) do update set nombre = excluded.nombre, familia = excluded.familia, clave_sat = excluded.clave_sat,
  ultima_compra = excluded.ultima_compra, estatus = excluded.estatus;

-- Articulos de cada registro de la bitacora
create table if not exists public.bitacora_articulos (
  id uuid primary key default gen_random_uuid(),
  bitacora_id uuid not null references public.bitacora (id),
  articulo_id uuid not null references public.articulos (id),
  cantidad numeric(12, 2) check (cantidad is null or cantidad > 0),
  created_by uuid not null default auth.uid() references public.profiles (id),
  created_at timestamptz not null default now(),
  unique (bitacora_id, articulo_id)
);
create index if not exists bitacora_articulos_articulo_idx on public.bitacora_articulos (articulo_id);
drop trigger if exists bitacora_articulos_audit on public.bitacora_articulos;
create trigger bitacora_articulos_audit after insert or update or delete on public.bitacora_articulos
  for each row execute function public.audit_row();

-- Solo se agregan articulos vendibles.
create or replace function public.bitacora_articulos_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.articulos where id = new.articulo_id and vendible) then
    raise exception 'Ese articulo esta suspendido o dado de baja';
  end if;
  new.created_by := coalesce(auth.uid(), new.created_by);
  return new;
end $$;
drop trigger if exists bitacora_articulos_guard on public.bitacora_articulos;
create trigger bitacora_articulos_guard before insert on public.bitacora_articulos
  for each row execute function public.bitacora_articulos_guard();
revoke all on function public.bitacora_articulos_guard() from public, anon, authenticated;

alter table public.bitacora_articulos enable row level security;
revoke all on public.bitacora_articulos from anon, authenticated;
grant select, delete on public.bitacora_articulos to authenticated;
grant insert (id, bitacora_id, articulo_id, cantidad) on public.bitacora_articulos to authenticated;
grant update (cantidad) on public.bitacora_articulos to authenticated;
drop policy if exists bitacora_articulos_select on public.bitacora_articulos;
create policy bitacora_articulos_select on public.bitacora_articulos for select to authenticated
  using (public.can_read_bitacora(bitacora_id));
drop policy if exists bitacora_articulos_insert on public.bitacora_articulos;
create policy bitacora_articulos_insert on public.bitacora_articulos for insert to authenticated
  with check (public.can_write_bitacora(bitacora_id));
drop policy if exists bitacora_articulos_update on public.bitacora_articulos;
create policy bitacora_articulos_update on public.bitacora_articulos for update to authenticated
  using (public.can_write_bitacora(bitacora_id)) with check (public.can_write_bitacora(bitacora_id));
drop policy if exists bitacora_articulos_delete on public.bitacora_articulos;
create policy bitacora_articulos_delete on public.bitacora_articulos for delete to authenticated
  using (public.can_write_bitacora(bitacora_id));

commit;

